    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    camMgr = adsk.cam.CAMManager.get()
    toolLibs = camMgr.libraryManager.toolLibraries
    def walk(url):
        try: childs = toolLibs.childAssetURLs(url)
        except: childs=[]
        return childs
    locs = [('Local', adsk.cam.LibraryLocations.LocalLibraryLocation),
            ('Hub', adsk.cam.LibraryLocations.HubLibraryLocation),
            ('Fusion', adsk.cam.LibraryLocations.Fusion360LibraryLocation)]
    for locname, loc in locs:
        try:
            root = toolLibs.urlByLocation(loc)
            for c in walk(root):
                print(locname, "/", c.leafName)
                if 'TIW' in c.leafName or 'tiw' in c.leafName.lower():
                    for cc in walk(c):
                        print("    ", cc.leafName)
        except Exception as e:
            print(locname, "err", e)

